package cn.local.rainreminder;
import android.app.*;import android.os.*;import android.widget.*;import android.view.*;import java.util.*;
public class UpdateActivity extends Activity {
 boolean resumed,installWhenReady;final Runnable listener=()->refresh();LinearLayout root,notes;String shownNotes="uninitialized";TextView state;ProgressBar progress;Button action,cancel;
 public void onCreate(Bundle b){super.onCreate(b);show();if(AppUpdates.latest(this)==null&&!AppUpdates.ready(this))AppUpdates.check(this);}
 void show(){root=Ui.screen(this,"应用更新");LinearLayout intro=Ui.card(this,root);intro.addView(Ui.text(this,"保持最新",24));intro.addView(Ui.hint(this,"当前版本 "+AppUpdates.version(this)));LinearLayout status=Ui.card(this,root);state=Ui.text(this,"",16);status.addView(state);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);status.addView(progress,new LinearLayout.LayoutParams(-1,Ui.dp(this,5)));action=Ui.primary(this,status,"检查更新",this::act);cancel=Ui.link(this,status,"取消下载",()->{AppUpdates.cancelled=true;cancel.setEnabled(false);});notes=Ui.card(this,root);renderNotes();Ui.link(this,root,"重新检查版本",()->AppUpdates.check(this));Switch auto=new Switch(this);auto.setTypeface(Ui.font(this));auto.setText("自动检查新版");auto.setChecked(AppUpdates.prefs(this).getBoolean("auto",true));auto.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,12));root.addView(auto);auto.setOnCheckedChangeListener((b,on)->AppUpdates.prefs(this).edit().putBoolean("auto",on).apply());root.addView(Ui.hint(this,"打开应用时每天最多自动检查一次，确认后才下载安装。网络需要能访问更新服务，下载失败可重试。"));refresh();}
 void renderNotes(){AppUpdates.Info info=AppUpdates.latest(this);String key=info==null?"":info.version+info.notes;if(key.equals(shownNotes))return;shownNotes=key;notes.removeAllViews();notes.addView(Ui.text(this,info==null?"更新方式":"新版 "+info.version,18));notes.addView(Ui.hint(this,info==null?"有新版时会在作业首页提示，下载后由系统确认安装。覆盖安装保留本机账号和课表。":String.format(Locale.CHINA,"约 %.1f MB",info.size/1000000.0)));if(info!=null&&!info.notes.isEmpty()){TextView text=Ui.hint(this,info.notes);text.setMaxLines(20);notes.addView(text);}}
 void act(){if(AppUpdates.busy)return;if(AppUpdates.ready(this)){AppUpdates.install(this);return;}AppUpdates.Info info=AppUpdates.latest(this);if(info==null)AppUpdates.check(this);else{installWhenReady=true;AppUpdates.download(this,info);}}
 void refresh(){if(state==null||isDestroyed())return;renderNotes();String value=AppUpdates.message;if(value.isEmpty())value=AppUpdates.ready(this)?"新版已下载，可以安装":AppUpdates.latest(this)==null?"检查是否有新版本":"有新版可以更新";state.setText(value);boolean downloading=AppUpdates.busy&&"downloading".equals(AppUpdates.phase);progress.setVisibility(AppUpdates.busy?View.VISIBLE:View.GONE);progress.setIndeterminate(!downloading);if(downloading)progress.setProgress(AppUpdates.progress);action.setEnabled(!AppUpdates.busy);action.setText(AppUpdates.busy?(downloading?"正在下载 "+Math.max(0,AppUpdates.progress)+"%":"正在检查…"):AppUpdates.ready(this)?"安装新版":AppUpdates.latest(this)!=null?"下载更新":"检查更新");cancel.setVisibility(downloading?View.VISIBLE:View.GONE);cancel.setEnabled(true);if(installWhenReady&&!AppUpdates.busy){installWhenReady=false;if(resumed&&"ready".equals(AppUpdates.phase)&&AppUpdates.ready(this))AppUpdates.install(this);} }
 protected void onResume(){super.onResume();resumed=true;AppUpdates.listeners.add(listener);if(AppUpdates.prefs(this).getBoolean("waitingPermission",false)){AppUpdates.prefs(this).edit().remove("waitingPermission").apply();if(getPackageManager().canRequestPackageInstalls())AppUpdates.install(this);}refresh();}
 protected void onPause(){resumed=false;AppUpdates.listeners.remove(listener);super.onPause();}
}
